mapper.select:
SELECT n.node_id, n.code, n.name, n.type, CASE n.type WHEN 1 THEN '捕捞企业' WHEN 2 THEN '养殖企业' WHEN 3 THEN '冷冻加工企业' WHEN 4 THEN '批发商' WHEN 5 THEN '零售商' ELSE '未知' END AS type_name, n.prov_id, p.prov_name, n.city_id, c.city_name, n.address, n.business_id, n.fishing_lic, n.aquaculture_lic, n.food_business_lic, n.corporation, n.telephone, n.reg_date, n.status, CASE n.status WHEN 1 THEN '待审核' WHEN 2 THEN '已通过' WHEN 3 THEN '禁用' ELSE '未知' END AS status_name, n.remarks FROM node_info n LEFT JOIN province p ON n.prov_id = p.prov_id LEFT JOIN city c ON n.city_id = c.city_id
AND n.name LIKE CONCAT('%', #{name}, '%')
AND n.type = #{type}
AND n.prov_id = #{provId}
AND n.status = #{status}
ORDER BY n.node_id DESC
